<?php
declare(strict_types=1);namespace Moves\App;
use InvalidArgumentException;use Moves\Services\{AccessPolicy,AppError,AppUrl,Csrf,Helpdesk,OrganizationContext,OrganizationFiles,OrganizationObligations,OrganizationTeam,SessionAuth};use Throwable;
final class ObligationActions
{
 public function handle(string$action):void{$user=SessionAuth::current();$org=OrganizationContext::current();if($user===null||$org===null||!Csrf::validate($_POST['csrf_token']??null)){AppError::render(403);return;}if(!OrganizationTeam::can((int)$user['id'],(int)$org['id'],'finance.manage')){AppError::render(403);return;}$service=new OrganizationObligations((int)$org['id']);try{$id=(int)filter_var($_POST['id']??0,FILTER_VALIDATE_INT);$message=match($action){'create'=>$this->create($service,(int)$user['id']),'update'=>$this->update($service,$id,(int)$user['id']),'complete'=>$this->status($service,$id,'completed',(int)$user['id']),'reopen'=>$this->status($service,$id,'pending',(int)$user['id']),'cancel'=>$this->status($service,$id,'cancelled',(int)$user['id']),default=>throw new InvalidArgumentException('Ação inválida.')};}catch(InvalidArgumentException$e){$message=['error',$e->getMessage()];}catch(Throwable$e){error_log('Realizze obligations: '.$e->getMessage());$message=['error','Não foi possível concluir a operação.'];}$_SESSION['obligations_flash']=$message;header('Cache-Control: no-store');header('Location: '.AppUrl::section('obrigacoes'),true,303);}
 public function download(int$id):void{$user=SessionAuth::current();$org=OrganizationContext::current();if($user===null||$org===null){AppError::render(404);return;}$row=(new OrganizationObligations((int)$org['id']))->attachment($id);if($row===null){AppError::render(404);return;}OrganizationFiles::stream((int)$org['id'],'obligations',$row);}
 private function create(OrganizationObligations$s,int$user):array{$r=$s->create($_POST,$user,Helpdesk::uploadedFiles('attachments'));return['success',$r['duplicate']?'Esta recorrência já havia sido criada.':($r['count']>1?$r['count'].' ocorrências criadas.':'Obrigação criada.')];}
 private function update(OrganizationObligations$s,int$id,int$user):array{$s->update($id,$_POST,$user,Helpdesk::uploadedFiles('attachments'));return['success','Obrigação atualizada.'];}
 private function status(OrganizationObligations$s,int$id,string$status,int$user):array{$s->setStatus($id,$status,$user);return['success',['completed'=>'Obrigação concluída.','pending'=>'Obrigação reaberta.','cancelled'=>'Obrigação cancelada.'][$status]];}
}
